package com.universalplatform.presence;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="attendance_record", uniqueConstraints=@UniqueConstraint(name="uq_attendance_record",columnNames={"tenant_id","live_class_id","membership_id"}))
class AttendanceRecord { @Id private UUID id; @Column(name="tenant_id",nullable=false) private UUID tenantId; @Column(name="live_class_id",nullable=false) private UUID liveClassId; @Column(name="membership_id",nullable=false) private UUID membershipId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=16) private AttendanceStatus status; @Column(nullable=false) private long presentSeconds; @Column(nullable=false) private Instant finalizedAt; @Column(nullable=false) private String source; private String notes; protected AttendanceRecord(){} AttendanceRecord(UUID id,UUID tenantId,UUID liveClassId,UUID membershipId,AttendanceStatus status,long presentSeconds,Instant finalizedAt,String source){this.id=id;this.tenantId=tenantId;this.liveClassId=liveClassId;this.membershipId=membershipId;this.status=status;this.presentSeconds=presentSeconds;this.finalizedAt=finalizedAt;this.source=source;} void revise(AttendanceStatus s,long seconds,Instant at,String source,String notes){this.status=s;this.presentSeconds=seconds;this.finalizedAt=at;this.source=source;this.notes=notes;} UUID id(){return id;} UUID liveClassId(){return liveClassId;} UUID membershipId(){return membershipId;} AttendanceStatus status(){return status;} long presentSeconds(){return presentSeconds;} Instant finalizedAt(){return finalizedAt;} String source(){return source;} String notes(){return notes;} }
